/**
 * Cached AI project briefing.
 *
 * Facts come from `ProjectWorkspaceSnapshot`; the model only writes the
 * narrative and risk list. Deterministic next actions are not generated by the
 * model, so a briefing cannot invent project state.
 */

import { createHash } from 'node:crypto'
import type { DshHarness } from './harness.ts'
import type { Project, ProjectService } from './projects.ts'
import type { PostgresProjectWorkspace, ProjectBriefing, ProjectWorkspaceSnapshot } from './workspace.ts'

export class BriefingError extends Error {
  readonly status = 502
  readonly code = 'BRIEFING_FAILED'

  constructor(message: string) {
    super(message)
    this.name = 'BriefingError'
  }
}

export interface ProjectBriefingResult extends ProjectBriefing {
  nextActions: ProjectWorkspaceSnapshot['nextActions']
  stale: boolean
}

export interface ProjectBriefingServiceDeps {
  projects: ProjectService
  workspace: PostgresProjectWorkspace
  harnessFactory: (cwd?: string) => DshHarness
  runPrompt?: (prompt: string, cwd: string) => Promise<string>
  model?: string
}

export class ProjectBriefingService {
  private readonly projects: ProjectService
  private readonly workspace: PostgresProjectWorkspace
  private readonly harnessFactory: (cwd?: string) => DshHarness
  private readonly runPrompt?: (prompt: string, cwd: string) => Promise<string>
  private readonly model?: string

  constructor(deps: ProjectBriefingServiceDeps) {
    this.projects = deps.projects
    this.workspace = deps.workspace
    this.harnessFactory = deps.harnessFactory
    this.runPrompt = deps.runPrompt
    this.model = deps.model
  }

  async get(projectId: string): Promise<ProjectBriefingResult | undefined> {
    const project = await this.projects.get(projectId)
    const snapshot = await this.workspace.getSnapshot(projectId)
    const cached = await this.workspace.getBriefing(projectId)
    if (cached === undefined) return undefined
    return {
      ...cached,
      nextActions: snapshot.nextActions,
      stale: cached.inputHash !== hashSnapshot(project, snapshot),
    }
  }

  async generate(projectId: string, options: { refresh?: boolean } = {}): Promise<ProjectBriefingResult> {
    const project = await this.projects.get(projectId)
    const snapshot = await this.workspace.getSnapshot(projectId)
    const inputHash = hashSnapshot(project, snapshot)
    const cached = await this.workspace.getBriefing(projectId)
    if (options.refresh !== true && cached !== undefined && cached.inputHash === inputHash) {
      return { ...cached, nextActions: snapshot.nextActions, stale: false }
    }

    const prompt = buildBriefingPrompt(project, snapshot)
    const raw = await this.runModel(prompt, project.rootPath)
    const parsed = parseBriefing(raw)
    const saved = await this.workspace.saveBriefing({
      projectId,
      inputHash,
      markdown: parsed.markdown,
      risks: parsed.risks,
      ...(this.model !== undefined ? { model: this.model } : {}),
    })
    return { ...saved, nextActions: snapshot.nextActions, stale: false }
  }

  private async runModel(prompt: string, cwd: string): Promise<string> {
    if (this.runPrompt !== undefined) return this.runPrompt(prompt, cwd)
    const harness = this.harnessFactory(cwd)
    const result = await harness.run(prompt)
    return result.text
  }
}

export function buildBriefingPrompt(project: Project, snapshot: ProjectWorkspaceSnapshot): string {
  const facts = {
    project: {
      id: project.id,
      name: project.name,
      rootPath: project.rootPath,
      organization: project.organization,
      ownerEmail: project.ownerEmail,
      status: project.status,
      currentStage: project.currentStage,
    },
    sdlc: {
      currentStage: snapshot.currentStage,
      stages: snapshot.stages,
      progress: snapshot.progress,
      nextActions: snapshot.nextActions,
      checklist: snapshot.checklist.filter((item) => item.status === 'open').map((item) => ({
        stage: item.stage,
        label: item.label,
        required: item.required,
      })),
      documents: snapshot.documents.map((document) => ({
        stage: document.stage,
        kind: document.kind,
        title: document.title,
        status: document.status,
      })),
    },
  }

  return `You are an AI delivery lead for a software project. Write a concise project briefing for the person opening the project dashboard.

Use ONLY the structured facts below. Do not invent status, decisions or documents. The next actions are computed by the system; explain them, but do not replace them with different actions.

${JSON.stringify(facts, null, 2)}

Write:
1. A one-paragraph summary of where the project is.
2. What is going well.
3. The most important risks or blockers, ordered by impact.
4. What the user should do next, referring to the exact computed actions.

Return ONLY JSON:
{
  "markdown": "# Project Briefing\\n\\n## Where we are\\n...\\n\\n## Risks\\n...\\n\\n## Next actions\\n...",
  "risks": ["risk 1", "risk 2"]
}

The markdown must be self-contained and readable in a Markdown renderer.`
}

export function parseBriefing(raw: string): { markdown: string; risks: string[] } {
  const text = raw.trim()
  if (text === '') throw new BriefingError('the model returned an empty briefing')
  const candidates = [text]
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i)
  if (fenced?.[1] !== undefined) candidates.push(fenced[1].trim())
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start >= 0 && end > start) candidates.push(text.slice(start, end + 1))

  for (const candidate of candidates) {
    try {
      const value: unknown = JSON.parse(candidate)
      if (value === null || typeof value !== 'object' || Array.isArray(value)) continue
      const record = value as Record<string, unknown>
      const markdown = typeof record.markdown === 'string' ? record.markdown.trim() : ''
      if (markdown === '') continue
      const risks = Array.isArray(record.risks)
        ? record.risks.filter((item): item is string => typeof item === 'string' && item.trim() !== '').slice(0, 12)
        : []
      return { markdown, risks }
    } catch {
      // Try the next candidate.
    }
  }

  return { markdown: text, risks: [] }
}

function hashSnapshot(project: Project, snapshot: ProjectWorkspaceSnapshot): string {
  return createHash('sha256')
    .update(JSON.stringify({ project, snapshot }))
    .digest('hex')
}
